-- Converted from COPY
INSERT INTO d105.ai_reports (ai_report_id, group_id, year_month, report_content, generated_at, expires_at, id) VALUES ('2', '13', '2025-09', '# 🏠 그룹 가계부 종합 리포트\n\n## 📊 2025년 9월 지출 분석\n\n1. 9월 한 달간 그룹 총 지출액은 387,465원으로, 멤버 1인 기준 부담이 전액 집중된 상태입니다.  \n2. 지출의 거의 절반(49.0%)이 주유비에 몰려 있어, 주유가 가장 큰 비용 부담임을 알 수 있습니다. 생활비(17.1%)와 미분류·교육/육아(각 12~13%)가 그 뒤를 잇고 있습니다.  \n3. 거래 건수는 총 15건으로, 생활비 관련 거래가 8건으로 가장 많아 일상 소비가 꾸준하지만, 주유는 3건으로 적은 횟수에 큰 비용이 집중된 특징을 보입니다.\n\n## 🎯 2025년 10월 스마트 지출 가이드\n\n1. 주유비 절감을 위해 차량 운행 계획을 미리 세우고, 주유 시 할인 혜택이나 적립 카드 활용을 권장합니다. 또한, 불필요한 외출 자제와 대중교통 병행으로 비용을 줄여보세요.  \n2. 다음 달 총 지출 목표를 35만원 내외로 설정하고, 생활비와 교육비 등 필수 지출은 유지하되, 미분류 항목은 지출 내역을 명확히 하여 불필요한 소비를 줄이는 데 집중합시다. 장기적으로는 지출 내역을 정기적으로 공유하며 모두가 함께 재정 관리를 실천하는 문화를 만들어가길 바랍니다.\n\n---\n\n모두가 함께 조금씩 신경 쓰면, 부담은 줄이고 알뜰한 생활이 가능해집니다. 10월도 힘내세요!', '2025-09-18 16:31:50.787037+09', NULL, '2');
INSERT INTO d105.ai_reports (ai_report_id, group_id, year_month, report_content, generated_at, expires_at, id) VALUES ('3', '13', '2025-07', '# 2025년 7월 그룹 지출 분석 및 8월 개선 가이드 리포트\n\n---\n\n## 2025년 7월 지출 분석\n\n1. 이번 달 그룹 총 지출은 3,855,100원으로, 2인 기준 1인당 약 192만 원의 부담이 발생하였습니다. 비교적 적은 인원 대비 지출 규모가 다소 높은 편으로, 지출 관리가 필요한 상황입니다.  \n2. 카테고리별로는 대형마트(24.3%)와 쇼핑(20.1%)이 전체 지출의 절반 가까이를 차지하며, 이 두 항목에서 과다 지출이 의심됩니다. 반면 외식(3.9%)과 배달(3.3%)은 적정 수준으로 보입니다.  \n3. 거래 건수는 총 69건으로, 마트/편의점 거래가 15건으로 가장 많아 생활 필수품 구매가 빈번함을 알 수 있습니다. 다만 대형마트 거래는 6건으로 적지만 금액이 커, 대형마트 중심의 대량 구매 습관이 뚜렷합니다.\n\n---\n\n## 2025년 8월 스마트 지출 가이드\n\n1. 대형마트 지출 절감을 위해 주간 할인 행사 및 쿠폰 활용을 적극 권장하며, 필요한 품목은 미리 목록을 작성해 불필요한 구매를 줄여보세요. 또한 쇼핑 카테고리도 계획적 구매와 중복 지출 점검으로 부담을 낮출 수 있습니다.  \n2. 8월 지출 목표는 총 3,200,000원 내외로 설정해 7월 대비 약 17% 절감하는 것을 권장하며, 장기적으로는 월별 지출 내역을 공유하고 함께 예산을 세워 꾸준한 재정 건전성을 확보해 나가길 바랍니다.\n\n---\n\n*친근한 말투로 구성원 모두가 쉽게 이해하고 실천할 수 있도록 작성하였으며, 함께 노력하는 그룹 재정 관리에 도움이 되길 바랍니다.*', '2025-09-26 16:48:33.850313+09', NULL, '3');
INSERT INTO d105.ai_reports (ai_report_id, group_id, year_month, report_content, generated_at, expires_at, id) VALUES ('4', '13', '2025-08', '# 2025년 8월 그룹 지출 분석 및 9월 개선 가이드 리포트\n\n---\n\n## 1. 2025년 8월 지출 분석\n\n1. 이번 달 그룹 총 지출액은 3,819,270원으로, 멤버 1인 기준으로 상당한 부담이 되는 수준입니다. 거래 건수는 39건으로 비교적 자주 소비가 이루어졌으나, 1인 그룹 특성상 지출 집중도가 높습니다.  \n2. 지출 중 주거/통신 항목이 21.0%로 가장 큰 비중을 차지하며, 저축/투자(13.1%)와 카드대금(11.8%)이 뒤를 잇고 있습니다. 생활 필수비용인 주거/통신 외에도 카드대금과 저축/투자 비중이 높아 재정 건전성은 양호하나, 일부 소액 지출이 다수 발생해 관리가 필요합니다.  \n3. 거래 패턴은 단일 멤버의 다양한 소액 소비가 혼재되어 있으며, 특히 대형마트, 보험, 교육/육아 등 필수 생활비가 꾸준히 발생하는 점에서 안정적인 소비 습관을 보입니다. 다만, 온라인 쇼핑과 배달 등 비정기적 소비도 적지 않아 지출 관리에 신경 써야 할 부분입니다.\n\n---\n\n## 2. 2025년 9월 스마트 지출 가이드\n\n1. 주거/통신 비용(800,000원, 21.0%) 절감을 위해 요금제 재검토, 중복 서비스 해지, 에너지 절약 실천 등 실질적 절약 방안을 권장합니다. 또한 카드대금과 저축/투자 항목은 유지하되, 온라인 쇼핑과 배달 지출을 월 10% 이상 줄이는 습관을 들이면 부담 완화에 도움이 됩니다.  \n2. 다음 달 지출 목표는 총 지출 3,400,000원 이하로 설정하고, 필수 생활비 위주로 예산을 관리하며 불필요한 소비는 최소화하는 것을 권장합니다. 장기적으로는 지출 내역을 정기적으로 점검하고, 그룹 멤버가 늘어날 경우 역할 분담과 공동 예산 관리 시스템 도입을 통해 재정 안정성을 높여 나가시길 바랍니다.\n\n---\n\n*친근한 말투로 정리하자면,*  \n“8월 한 달 동안 꽤 많은 지출이 있었는데요, 특히 주거와 통신비가 큰 비중을 차지했어요. 9월에는 요금제나 카드 사용 내역을 꼼꼼히 살펴보고, 온라인 쇼핑과 배달은 조금씩 줄여보는 게 어떨까요? 부담을 조금만 덜어내면 더 여유로운 재정 관리가 가능할 거예요. 앞으로도 꾸준히 지출을 체크하면서 모두가 함께하는 그룹 재정 관리, 꼭 성공하시길 응원합니다!”', '2025-09-26 16:49:04.059148+09', NULL, '4');


